 71→// GetCommitLinking returns the effective commit linking mode.
 72→// Returns the explicit value if set, otherwise defaults to "prompt"
 73→// to preserve existing user behavior.
 74→func (s *EntireSettings) GetCommitLinking() string {
 75→	if s.CommitLinking != "" {
 76→		return s.CommitLinking
 77→	}
 78→	return CommitLinkingPrompt
 79→}
