 81→// Load loads the Entire settings from .entire/settings.json,
 82→// then applies any overrides from .entire/settings.local.json if it exists.
 83→// Returns default settings if neither file exists.
 84→// Works correctly from any subdirectory within the repository.
 85→func Load(ctx context.Context) (*EntireSettings, error) {
 86→	// Get absolute paths for settings files
 87→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
 88→	if err != nil {
 89→		settingsFileAbs = EntireSettingsFile // Fallback to relative
 90→	}
 91→	localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
 92→	if err != nil {
 93→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
 94→	}
 95→
 96→	// Load base settings
 97→	settings, err := loadFromFile(settingsFileAbs)
 98→	if err != nil {
 99→		return nil, fmt.Errorf("reading settings file: %w", err)
100→	}
101→
102→	// Apply local overrides if they exist
103→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
104→	if err != nil {
105→		if !os.IsNotExist(err) {
106→			return nil, fmt.Errorf("reading local settings file: %w", err)
107→		}
108→		// Local file doesn't exist, continue without overrides
109→	} else {
110→		if err := mergeJSON(settings, localData); err != nil {
111→			return nil, fmt.Errorf("merging local settings: %w", err)
112→		}
113→	}
114→
115→	return settings, nil
116→}
117→
118→// LoadFromFile loads settings from a specific file path without merging local overrides.
119→// Returns default settings if the file doesn't exist.
120→// Use this when you need to display individual settings files separately.
121→func LoadFromFile(filePath string) (*EntireSettings, error) {
122→	return loadFromFile(filePath)
123→}
124→
125→// loadFromFile loads settings from a specific file path.
126→// Returns default settings if the file doesn't exist.
127→func loadFromFile(filePath string) (*EntireSettings, error) {
128→	settings := &EntireSettings{
129→		Enabled: true, // Default to enabled
130→	}
131→
132→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
133→	if err != nil {
134→		if os.IsNotExist(err) {
135→			return settings, nil
136→		}
137→		return nil, fmt.Errorf("%w", err)
138→	}
139→
140→	dec := json.NewDecoder(bytes.NewReader(data))
141→	dec.DisallowUnknownFields()
142→	if err := dec.Decode(settings); err != nil {
143→		return nil, fmt.Errorf("parsing settings file: %w", err)
144→	}
145→
146→	// Validate commit_linking if set
147→	if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
148→		return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
149→	}
150→
151→	return settings, nil
152→}
