154→// mergeJSON merges JSON data into existing settings.
155→// Only non-zero values from the JSON override existing settings.
156→func mergeJSON(settings *EntireSettings, data []byte) error {
157→	// First, validate that there are no unknown keys using strict decoding
158→	dec := json.NewDecoder(bytes.NewReader(data))
159→	dec.DisallowUnknownFields()
160→	var temp EntireSettings
161→	if err := dec.Decode(&temp); err != nil {
162→		return fmt.Errorf("parsing JSON: %w", err)
163→	}
164→
165→	// Parse into a map to check which fields are present
166→	var raw map[string]json.RawMessage
167→	if err := json.Unmarshal(data, &raw); err != nil {
168→		return fmt.Errorf("parsing JSON: %w", err)
169→	}
170→
171→	// Override enabled if present
172→	if enabledRaw, ok := raw["enabled"]; ok {
173→		var e bool
174→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
175→			return fmt.Errorf("parsing enabled field: %w", err)
176→		}
177→		settings.Enabled = e
178→	}
179→
180→	// Override local_dev if present
181→	if localDevRaw, ok := raw["local_dev"]; ok {
182→		var ld bool
183→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
184→			return fmt.Errorf("parsing local_dev field: %w", err)
185→		}
186→		settings.LocalDev = ld
187→	}
188→
189→	// Override absolute_git_hook_path if present
190→	if ahpRaw, ok := raw["absolute_git_hook_path"]; ok {
191→		var ahp bool
192→		if err := json.Unmarshal(ahpRaw, &ahp); err != nil {
193→			return fmt.Errorf("parsing absolute_git_hook_path field: %w", err)
194→		}
195→		settings.AbsoluteGitHookPath = ahp
196→	}
197→
198→	// Override log_level if present and non-empty
199→	if logLevelRaw, ok := raw["log_level"]; ok {
200→		var ll string
201→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
202→			return fmt.Errorf("parsing log_level field: %w", err)
203→		}
204→		if ll != "" {
205→			settings.LogLevel = ll
206→		}
207→	}
208→
209→	// Merge strategy_options if present
210→	if optionsRaw, ok := raw["strategy_options"]; ok {
211→		var opts map[string]any
212→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
213→			return fmt.Errorf("parsing strategy_options field: %w", err)
214→		}
215→		if settings.StrategyOptions == nil {
216→			settings.StrategyOptions = opts
217→		} else {
218→			for k, v := range opts {
219→				settings.StrategyOptions[k] = v
220→			}
221→		}
222→	}
223→
224→	// Override telemetry if present
225→	if telemetryRaw, ok := raw["telemetry"]; ok {
226→		var t bool
227→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
228→			return fmt.Errorf("parsing telemetry field: %w", err)
229→		}
230→		settings.Telemetry = &t
231→	}
232→
233→	// Override commit_linking if present and non-empty
234→	if commitLinkingRaw, ok := raw["commit_linking"]; ok {
235→		var cl string
236→		if err := json.Unmarshal(commitLinkingRaw, &cl); err != nil {
237→			return fmt.Errorf("parsing commit_linking field: %w", err)
238→		}
239→		if cl != "" {
240→			switch cl {
241→			case CommitLinkingAlways, CommitLinkingPrompt:
242→				settings.CommitLinking = cl
243→			default:
244→				return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
245→			}
246→		}
247→	}
248→
249→	return nil
250→}
