252→// IsSetUp returns true if Entire has been set up in the current repository.
253→// This checks if .entire/settings.json exists.
254→// Use this to avoid creating files/directories in repos where Entire was never enabled.
255→func IsSetUp(ctx context.Context) bool {
256→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
257→	if err != nil {
258→		return false
259→	}
260→	_, err = os.Stat(settingsFileAbs)
261→	return err == nil
262→}
263→
264→// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
265→// This checks if .entire/settings.json exists AND has enabled: true.
266→// Use this for hooks that should be no-ops when Entire is not active.
267→func IsSetUpAndEnabled(ctx context.Context) bool {
268→	if !IsSetUp(ctx) {
269→		return false
270→	}
271→	s, err := Load(ctx)
272→	if err != nil {
273→		return false
274→	}
275→	return s.Enabled
276→}
