278→// IsSummarizeEnabled checks if auto-summarize is enabled in settings.
279→// Returns false by default if settings cannot be loaded or the key is missing.
280→func IsSummarizeEnabled(ctx context.Context) bool {
281→	settings, err := Load(ctx)
282→	if err != nil {
283→		return false
284→	}
285→	return settings.IsSummarizeEnabled()
