288→// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
289→func (s *EntireSettings) IsSummarizeEnabled() bool {
290→	if s.StrategyOptions == nil {
291→		return false
292→	}
293→	summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
294→	if !ok {
295→		return false
296→	}
297→	enabled, ok := summarizeOpts["enabled"].(bool)
298→	if !ok {
299→		return false
300→	}
301→	return enabled
302→}
