304→// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
305→// Returns true if push_sessions is explicitly set to false.
306→func (s *EntireSettings) IsPushSessionsDisabled() bool {
307→	if s.StrategyOptions == nil {
308→		return false
309→	}
310→	val, exists := s.StrategyOptions["push_sessions"]
311→	if !exists {
312→		return false
313→	}
314→	if boolVal, ok := val.(bool); ok {
315→		return !boolVal // disabled = !push_sessions
316→	}
317→	return false
318→}
