330→// saveToFile saves settings to the specified file path.
331→func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
332→	// Get absolute path for the file
333→	filePathAbs, err := paths.AbsPath(ctx, filePath)
334→	if err != nil {
335→		filePathAbs = filePath // Fallback to relative
336→	}
337→
338→	// Ensure directory exists
339→	dir := filepath.Dir(filePathAbs)
340→	if err := os.MkdirAll(dir, 0o750); err != nil {
341→		return fmt.Errorf("creating settings directory: %w", err)
342→	}
343→
344→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
345→	if err != nil {
346→		return fmt.Errorf("marshaling settings: %w", err)
347→	}
348→
349→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
350→	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
351→		return fmt.Errorf("writing settings file: %w", err)
352→	}
353→	return nil
354→}
